    p.reg('fault','Memoria de UC_SUP: RUN_STARTED / ABORT_SEEN / CLOCK_FAULT\nTres bits; no duplicar en datapath\nEV_RAW=ABORT_SEEN | CLOCK_FAULT; retener eventos breves\nEV_REF, ABORT_REF y READY_REF: dos FF REF cada uno\nCLOCK_FAULT → G_ERR; phy_abort solo no crea esa causa',1010,1130,720,180)
    p.wire('inhibit','reset','INHIBIT: aserción / liberación',[(850,900),(850,1090),(405,1090)],control=True,ports='exitX=0;exitY=0.5;entryX=0.5;entryY=0;')
